import { Table, BooleanColumn, StringColumn, ReferenceColumn, GenericColumn } from '../../db'

export const sys_app = Table({
    name: 'sys_app',
    extends: 'sys_scope',
    schema: {
        hide_on_ui: BooleanColumn({
            mandatory: false,
            label: 'Hidden on ui',
            read_only: false,
            active: true,
            default: false,
        }),
        installed_as_dependency: BooleanColumn({
            mandatory: false,
            label: 'Installed via Dependency',
            read_only: false,
            active: true,
            default: false,
        }),
        license_definition: ReferenceColumn({
            mandatory: false,
            label: 'License Definition',
            read_only: false,
            active: true,
            referenceTable: 'sys_app_license_defn',
        }),
        menu: ReferenceColumn({
            mandatory: false,
            label: 'Menu',
            read_only: false,
            active: true,
            referenceTable: 'sys_app_application',
        }),
        store_correlation_id: StringColumn({
            mandatory: false,
            label: 'Store correlation ID',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        store_url: StringColumn({
            mandatory: false,
            label: 'Store URL',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        sys_code: StringColumn({
            mandatory: false,
            label: 'Code',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        uninstall_blocked: BooleanColumn({
            mandatory: false,
            label: 'Uninstall Blocked',
            read_only: false,
            active: true,
            default: false,
        }),
        user_role: ReferenceColumn({
            mandatory: false,
            label: 'User role',
            read_only: false,
            active: true,
            referenceTable: 'sys_user_role',
        }),
    },
})
